namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch round.",
                    "Spread crushed tomatoes over the dough.",
                    "Tear mozzarella and distribute evenly.",
                    "Bake for 10-12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 54
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and pepper.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Quickly stir in egg mixture to create a creamy sauce.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred.",
                    "Sauté onion, garlic, and ginger in a pot.",
                    "Add tomato sauce and spices; simmer 15 minutes.",
                    "Stir in cream and add grilled chicken.",
                    "Simmer 10 minutes and serve over basmati rice."
                ],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish packed with vegetables.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Eggs"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry tofu until golden, then set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss with bean sprouts and tofu.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 26
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with lettuce, tomato, cheese, sour cream, and salsa.",
                    "Serve with lime wedges."
                ],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour ramekins.",
                    "Melt chocolate and butter together.",
                    "Whisk eggs and sugar until thick, then fold in chocolate mixture.",
                    "Add flour and vanilla; mix until just combined.",
                    "Pour into ramekins and bake for 12-14 minutes.",
                    "Invert onto plates and serve immediately."
                ],
                TotalRatings = 20, RatingSum = 96
            },
            new Recipe
            {
                Id = 7, Title = "Greek Salad", Category = "Mediterranean",
                Description = "A refreshing salad with crisp vegetables and tangy feta.",
                Ingredients = ["Cucumber", "Tomatoes", "Red onion", "Kalamata olives", "Feta cheese", "Olive oil", "Oregano"],
                Steps = [
                    "Chop cucumber, tomatoes, and red onion into chunks.",
                    "Combine vegetables in a large bowl.",
                    "Add olives and crumbled feta.",
                    "Drizzle with olive oil and sprinkle with oregano.",
                    "Toss gently and serve."
                ],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Miso Ramen", Category = "Japanese",
                Description = "A warming bowl of noodles in a savory miso broth.",
                Ingredients = ["Ramen noodles", "White miso paste", "Chicken broth", "Soft-boiled egg", "Chashu pork", "Corn", "Green onions", "Nori"],
                Steps = [
                    "Bring chicken broth to a simmer.",
                    "Dissolve miso paste into the broth.",
                    "Cook ramen noodles according to package directions.",
                    "Place noodles in a bowl and ladle broth over them.",
                    "Top with sliced chashu, soft-boiled egg, corn, nori, and green onions.",
                    "Serve immediately while hot."
                ],
                TotalRatings = 9, RatingSum = 41
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = submission.Title,
                Category = submission.Category,
                Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
                Ingredients = submission.Ingredients
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList(),
                Steps = submission.Steps
                    .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .ToList()
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

