@page "/submit"
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (!string.IsNullOrEmpty(successMessage))
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="submission.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="submission.Category" class="form-select">
            <option value="">-- Select a category --</option>
            @foreach (var cat in categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="submission.Ingredients" class="form-control" rows="6"
            placeholder="Enter one ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <div class="form-text">Enter one ingredient per line.</div>
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="submission.Steps" class="form-control" rows="6"
            placeholder="Enter one step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        <div class="form-text">Enter one step per line.</div>
    </div>

    <button type="submit" class="btn btn-success" disabled="@(!IsFormValid)">
        Submit Recipe
    </button>
</EditForm>

@code {
    private RecipeHub.Models.RecipeSubmission submission = new();
    private IReadOnlyList<string> categories = [];
    private string? successMessage;

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (!IsFormValid) return;

        var recipe = RecipeService.AddRecipe(submission);
        successMessage = $"\"{recipe.Title}\" has been submitted! View it in the {recipe.Category} category.";
        submission = new();
    }
}

@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="d-inline-block">
    <span class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hoverRating > 0 ? hoverRating : userRating) ? "star-filled" : "star-empty")"
                  role="button"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoverRating = star"
                  @onmouseout="() => hoverRating = 0">
                @(star <= (hoverRating > 0 ? hoverRating : userRating) ? "★" : "☆")
            </span>
        }
    </span>

    @if (userRating > 0)
    {
        <span class="ms-2 text-success"><small>You rated @userRating star(s). Thank you!</small></span>
    }
    else
    {
        <span class="ms-2 text-muted"><small>Click to rate</small></span>
    }

    @if (currentRecipe is not null && currentRecipe.TotalRatings > 0)
    {
        <div class="mt-1">
            <small class="text-muted">
                Average: @currentRecipe.AverageRating.ToString("F1") / 5
                · @currentRecipe.TotalRatings rating(s)
            </small>
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int userRating;
    private int hoverRating;
    private RecipeHub.Models.Recipe? currentRecipe;

    protected override void OnParametersSet()
    {
        currentRecipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        if (userRating > 0) return; // only allow one rating per session
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        currentRecipe = RecipeService.GetById(RecipeId);
    }
}

